#!/usr/bin/env python3
"""Emit only implemented ABI families. Unknown signatures fail with a reason."""
import json,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def generate(check=False):
    profile=json.loads((ROOT/'tools/hook-families/profile.json').read_text())
    outputs={}
    for hook in profile:
        if hook['type']!='Terraria.Player' or hook['result'] not in ('System.Int32','System.Boolean') or hook['parameters']!=['System.Int32']:
            raise ValueError('Unsupported hook ABI family: '+hook['method'])
        if not all(re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*',hook[k])for k in ['name','method','export']):raise ValueError('Invalid generated identifier')
        for template,target in [('api','src/Ivy.Api/Generated/'+hook['name']+'Hooks.g.cs'),('host','src/Ivy.Android/Generated/'+hook['name']+'Bridge.g.cs'),('native','native/ivy-native/'+hook['export']+'.g.inc')]:
            content=(ROOT/('tools/hook-families/'+template+'.txt')).read_text()
            for key in ['type','name','method','export','result']:content=content.replace('@@'+key.upper()+'@@',hook[key])
            boolean=hook['result']=='System.Boolean'
            for key,value in {'CS_RESULT':'bool' if boolean else 'int','NATIVE_RESULT':'bool' if boolean else 'int32_t','ENCODE':('@@NAME@@Hooks.Invoke(self,argument)?1:0' if boolean else '@@NAME@@Hooks.Invoke(self,argument)').replace('@@NAME@@',hook['name']),'DECODE':'result!=0' if boolean else 'result','DEFAULT':'0' if boolean else '-1','FAMILY':'bool(int)' if boolean else 'int(int)'}.items():content=content.replace('@@'+key+'@@',value)
            outputs[ROOT/target]=content
    names=[h['name']for h in profile]
    if len(names)!=len(set(names)) or len({h['export']for h in profile})!=len(profile):raise ValueError('Duplicate hook family name/export')
    outputs[ROOT/'src/Ivy.Api/Generated/ReturnHookFamilies.g.cs']='// <auto-generated/>\nnamespace Ivy.Runtime;\ninternal static class ReturnHookFamilies {\n internal static bool HasHandlers => '+(' || '.join(h['name']+'Hooks.HasHandlers'for h in profile)or'false')+';\n internal static void RemoveOwner(HookOwner owner){'+''.join(h['name']+'Hooks.RemoveOwner(owner);'for h in profile)+'}\n}\n'
    outputs[ROOT/'src/Ivy.Android/Generated/ReturnHookFamilies.g.cs']='// <auto-generated/>\nusing Ivy.Runtime;\nnamespace Ivy.AndroidHost;\ninternal static partial class NativeWorldBridge {\n private static void InstallGeneratedFamilies(Il2CppAccess access){'+''.join('Install'+h['name']+'(access);'for h in profile)+'}\n private static void DispatchGeneratedFamilies(bool enabled){'+''.join('if(installed'+h['name']+')Set'+h['name']+'Native(enabled && '+h['name']+'Hooks.HasHandlers?1:0);'for h in profile)+'}\n}\n'
    outputs[ROOT/'native/ivy-native/return_hooks.g.inc']='// <auto-generated/>\n'+''.join('#include "'+h['export']+'.g.inc"\n'for h in profile)
    for path,text in outputs.items():
        if check:
            if not path.exists()or path.read_text()!=text:raise ValueError('Generated hook out of date: '+str(path))
        else:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text)
    print(f'{len(profile)} ABI family target(s), {len(outputs)} generated files verified'if check else f'{len(outputs)} hook files generated')
if __name__=='__main__':generate('--check'in sys.argv)
